-- Varalakshmi's Prana Pratishtha: the note and the instruction describe this
-- step, not Ganesha Chaturthi, an edition, or a verse it no longer carries.
-- Generated by scripts/build-prana-note-repair.mjs; see its header.

begin;

update public.pooja_steps set philosophy_en = 'Asunite punarasmasu chakshuh, "give us back our sight". The verse asks that breath, sight and gladness be returned to us before it asks anything of the goddess. Only then do the lines turn to her, and they turn in the feminine: avahita bhava, sthapita bhava, varada bhava, be invoked, be established, be the giver of boons. From that moment the kalasham is treated as a presence, which is why it is released the next day with a step of its own rather than simply being put away.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha' and philosophy_en is distinct from 'Asunite punarasmasu chakshuh, "give us back our sight". The verse asks that breath, sight and gladness be returned to us before it asks anything of the goddess. Only then do the lines turn to her, and they turn in the feminine: avahita bhava, sthapita bhava, varada bhava, be invoked, be established, be the giver of boons. From that moment the kalasham is treated as a presence, which is why it is released the next day with a step of its own rather than simply being put away.';

update public.pooja_steps set instruction_en = 'Touch the kalasham with the fingertips of the right hand and ask the life breath to settle into it. From here the kalasham is treated as present, not as an arrangement of vessels. The closing lines address the goddess in the feminine: avahita, sthapita, varada.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha' and instruction_en is distinct from 'Touch the kalasham with the fingertips of the right hand and ask the life breath to settle into it. From here the kalasham is treated as present, not as an arrangement of vessels. The closing lines address the goddess in the feminine: avahita, sthapita, varada.';

update public.pooja_steps set instruction_ta = 'வலது கை விரல் நுனிகளால் கலசத்தைத் தொட்டு, உயிர்ப்பு அதில் நிலைபெறும்படி வேண்டவும். இதற்குப் பின் கலசம் பாத்திரங்களின் அமைப்பு அல்ல; எழுந்தருளியிருப்பவளாகவே கருதப்படுகிறது. இறுதி வரிகள் தேவியை ஸ்த்ரீலிங்கத்தில் அழைக்கின்றன — ஆவாஹிதா, ஸ்தாபிதா, வரதா.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha' and instruction_ta is distinct from 'வலது கை விரல் நுனிகளால் கலசத்தைத் தொட்டு, உயிர்ப்பு அதில் நிலைபெறும்படி வேண்டவும். இதற்குப் பின் கலசம் பாத்திரங்களின் அமைப்பு அல்ல; எழுந்தருளியிருப்பவளாகவே கருதப்படுகிறது. இறுதி வரிகள் தேவியை ஸ்த்ரீலிங்கத்தில் அழைக்கின்றன — ஆவாஹிதா, ஸ்தாபிதா, வரதா.';

do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha'
     and philosophy_en = 'Asunite punarasmasu chakshuh, "give us back our sight". The verse asks that breath, sight and gladness be returned to us before it asks anything of the goddess. Only then do the lines turn to her, and they turn in the feminine: avahita bhava, sthapita bhava, varada bhava, be invoked, be established, be the giver of boons. From that moment the kalasham is treated as a presence, which is why it is released the next day with a step of its own rather than simply being put away.'
     and instruction_en = 'Touch the kalasham with the fingertips of the right hand and ask the life breath to settle into it. From here the kalasham is treated as present, not as an arrangement of vessels. The closing lines address the goddess in the feminine: avahita, sthapita, varada.'
     and instruction_ta = 'வலது கை விரல் நுனிகளால் கலசத்தைத் தொட்டு, உயிர்ப்பு அதில் நிலைபெறும்படி வேண்டவும். இதற்குப் பின் கலசம் பாத்திரங்களின் அமைப்பு அல்ல; எழுந்தருளியிருப்பவளாகவே கருதப்படுகிறது. இறுதி வரிகள் தேவியை ஸ்த்ரீலிங்கத்தில் அழைக்கின்றன — ஆவாஹிதா, ஸ்தாபிதா, வரதா.';
  if n <> 1 then raise exception 'Prana Pratishtha: a field was not written'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha'
     and position('asunīte punarasmāsu cakṣuḥ' in mantra_translit) > 0
     and position('āvāhitā bhava' in mantra_translit) > 0
     and position('sthāpitā bhava' in mantra_translit) > 0
     and position('varadā bhava' in mantra_translit) > 0;
  if n <> 1 then raise exception 'Prana Pratishtha: the note quotes a phrase the mantra does not have'; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
